-- Query examples for the SQLite events.sqlite database generated by the pipeline.
-- Amounts are gross purchase item values, NOT platform margin or net revenue.

-- 1. Daily purchase value and distinct purchasing sessions.
SELECT
    substr(event_time, 1, 10) AS purchase_date,
    COUNT(*) AS purchase_line_events,
    ROUND(SUM(price), 2) AS gross_item_value,
    COUNT(DISTINCT user_id || '|' || user_session) AS observed_purchasing_sessions
FROM events
WHERE event_type = 'purchase'
GROUP BY substr(event_time, 1, 10)
ORDER BY purchase_date;

-- 2. Session-level conversion, including sessions that never purchased.
SELECT
    COUNT(*) AS total_identified_sessions,
    SUM(CASE WHEN first_purchase_at IS NOT NULL THEN 1 ELSE 0 END) AS purchasing_sessions,
    ROUND(AVG(CASE WHEN first_purchase_at IS NOT NULL THEN 1.0 ELSE 0.0 END), 5) AS purchase_rate
FROM sessions;

-- 3. Gross purchase item value for popular categories.
SELECT
    COALESCE(category_code, '[unknown]') AS category,
    COUNT(*) AS purchased_items,
    ROUND(SUM(price), 2) AS gross_item_value
FROM events
WHERE event_type = 'purchase'
GROUP BY COALESCE(category_code, '[unknown]')
ORDER BY gross_item_value DESC;
